package shop.ultimatesmp.crates;
import org.junit.jupiter.api.*;import org.junit.jupiter.api.io.TempDir;import static org.junit.jupiter.api.Assertions.*;import static org.mockito.Mockito.*;import org.bukkit.Material;import org.bukkit.inventory.ItemStack;import java.nio.file.Path;import java.util.*;import java.util.concurrent.atomic.AtomicInteger;
class CratesTest {
 @TempDir Path temp;
 static ItemStack item(Material material,int count,String variant){ItemStack s=mock(ItemStack.class);AtomicInteger amount=new AtomicInteger(count);when(s.getType()).thenReturn(material);when(s.getAmount()).thenAnswer(i->amount.get());doAnswer(i->{amount.set(i.getArgument(0));return null;}).when(s).setAmount(anyInt());when(s.getMaxStackSize()).thenReturn(64);when(s.clone()).thenAnswer(i->item(material,amount.get(),variant));when(s.isSimilar(any())).thenAnswer(i->{ItemStack other=i.getArgument(0);return other!=null&&material==other.getType()&&variant.equals(other.toString());});when(s.toString()).thenReturn(variant);return s;}
 @Test void relativeWeightsHaveExactBoundaries(){assertEquals(0,Crate.select(List.of(1,3,6),0));assertEquals(1,Crate.select(List.of(1,3,6),1));assertEquals(1,Crate.select(List.of(1,3,6),3));assertEquals(2,Crate.select(List.of(1,3,6),4));assertEquals(2,Crate.select(List.of(1,3,6),9));assertThrows(IllegalArgumentException.class,()->Crate.select(List.of(1,0),0));assertThrows(IllegalArgumentException.class,()->Crate.select(List.of(1),1));}
 @Test void fullInventoryRejectsWithoutChangingOriginal(){var full=item(Material.STONE,64,"stone");ItemStack[] source={full};assertNull(InventoryGrant.add(source,item(Material.DIAMOND,2,"diamond")));assertEquals(64,full.getAmount());assertSame(full,source[0]);}
 @Test void mergeRespectsItemIdentityAndReturnsIndependentPlan(){var original=item(Material.DIAMOND,63,"named-A");ItemStack[] source={original,null};ItemStack[] next=InventoryGrant.add(source,item(Material.DIAMOND,3,"named-A"));assertNotNull(next);assertEquals(64,next[0].getAmount());assertEquals(2,next[1].getAmount());assertEquals(63,original.getAmount());assertNull(source[1]);assertNull(InventoryGrant.add(new ItemStack[]{original},item(Material.DIAMOND,1,"named-B")));}
 @Test void freedLastKeySlotCanReceiveReward(){ItemStack[] source={null};var reward=item(Material.DIAMOND,16,"diamond");var next=InventoryGrant.add(source,reward);assertEquals(16,next[0].getAmount());assertNull(source[0]);assertNotSame(reward,next[0]);}
 @Test void selectiveInventoryCannotFilterUnwantedRewards(){var diamonds=item(Material.DIAMOND,60,"diamond");ItemStack[] source={diamonds};assertFalse(InventoryGrant.acceptsAll(source,List.of(item(Material.DIAMOND,1,"diamond"),item(Material.EMERALD,1,"emerald"))));assertEquals(60,diamonds.getAmount());assertTrue(InventoryGrant.acceptsAll(new ItemStack[]{diamonds,null},List.of(item(Material.DIAMOND,1,"diamond"),item(Material.EMERALD,1,"emerald"))));}
 @Test void templatesAreCopied(){var source=item(Material.DIAMOND,5,"named");var reward=new Crate.Reward(source,10);reward.item().setAmount(1);assertEquals(5,source.getAmount());assertThrows(IllegalArgumentException.class,()->new Crate("../oops","Crate",1,List.of()));}
 @Test void localRevisionGuardAndAtomicSave()throws Exception{var store=new CrateStore(temp.resolve("crates.yml"),null,"","");store.initialize();assertTrue(store.save("rare",0,"revision: 1\nname: Rare\n"));assertFalse(store.save("rare",0,"revision: 1\n"));assertTrue(store.save("rare",1,"revision: 2\nname: New\n"));assertFalse(store.save("rare",1,"revision: 2\nname: Stale\n"));assertTrue(store.load().get("rare").contains("New"));}
 @Test void sharedDefinitionsVisibleAcrossServersAndConflictsPreserved()throws Exception{String url=System.getenv("TEST_JDBC_URL");Assumptions.assumeTrue(url!=null);String user=System.getenv().getOrDefault("TEST_DB_USER","root"),pass=System.getenv().getOrDefault("TEST_DB_PASSWORD","");var a=new CrateStore(temp.resolve("unused"),url,user,pass);var b=new CrateStore(temp.resolve("unused2"),url,user,pass);a.initialize();String id="test_"+UUID.randomUUID().toString().substring(0,8);assertTrue(a.save(id,0,"revision: 1\nname: First\n"));assertEquals(a.load().get(id),b.load().get(id));assertTrue(b.save(id,1,"revision: 2\nname: Second\n"));assertFalse(a.save(id,1,"revision: 2\nname: Stale\n"));assertTrue(a.load().get(id).contains("Second"));}
}
